head.b:skin:
/* ============================================
   PENA EDUKASI - MODERN BLOGGER TEMPLATE V2
   Background: #F8F9FA | Primary: #1a8a9e
   ============================================ */

:root {
  --bg-primary: #F8F9FA;
  --bg-card: #FFFFFF;
  --bg-dark: #1a1f2e;
  --bg-dark-card: #242938;
  --text-primary: #1e3a5f;
  --text-secondary: #5a6f8a;
  --text-dark-primary: #e2e8f0;
  --text-dark-secondary: #94a3b8;
  --accent: #1a8a9e;
  --accent-hover: #15707f;
  --accent-light: rgba(26,138,158,0.1);
  --border-color: #e2e8f0;
  --border-dark: #2d3548;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
  --radius: 12px;
  --radius-sm: 8px;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-serif: 'Playfair Display', Georgia, serif;
  --topbar-h: 64px;
  --sidebar-w: 270px;
  --transition: 0.3s cubic-bezier(0.4,0,0.2,1);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
a { color: var(--accent); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--accent-hover); }
img { max-width: 100%; height: auto; display: block; }

/* === DARK MODE === */
body.dark-mode { background: var(--bg-dark); color: var(--text-dark-primary); }
body.dark-mode .topbar { background: var(--bg-dark-card); border-color: var(--border-dark); }
body.dark-mode .sidebar-left { background: var(--bg-dark-card); border-color: var(--border-dark); }
body.dark-mode .sidebar-right-inner { background: var(--bg-dark-card); border-color: var(--border-dark); }
body.dark-mode .article-card { background: var(--bg-dark-card); border-color: var(--border-dark); }
body.dark-mode .article-card .card-title { color: var(--text-dark-primary); }
body.dark-mode .article-card .card-meta { color: var(--text-dark-secondary); border-color: var(--border-dark); }
body.dark-mode .article-card .card-excerpt { color: var(--text-dark-secondary); }
body.dark-mode .grid-section-title { color: var(--text-dark-primary); }
body.dark-mode .post-body { color: var(--text-dark-primary); }
body.dark-mode .post-title-single { color: var(--text-dark-primary); }
body.dark-mode .related-card { background: var(--bg-dark-card); border-color: var(--border-dark); }
body.dark-mode .related-card h4 { color: var(--text-dark-primary); }
body.dark-mode .footer-wrapper { background: var(--bg-dark-card); border-color: var(--border-dark); }
body.dark-mode .footer-wrapper,
body.dark-mode .footer-wrapper a { color: var(--text-dark-secondary); }
body.dark-mode .search-box input { background: #1a1f2e; color: var(--text-dark-primary); border-color: var(--border-dark); }
body.dark-mode .popular-item .pop-title { color: var(--text-dark-primary); }
body.dark-mode .popular-item .pop-date { color: var(--text-dark-secondary); }
body.dark-mode .popular-item { border-color: var(--border-dark); }
body.dark-mode .category-tag { background: rgba(26,138,158,0.2); color: #5cc8db; }
body.dark-mode .breadcrumb a, body.dark-mode .breadcrumb span { color: var(--text-dark-secondary); }
body.dark-mode .sidebar-brand h2 { color: #5cc8db; }
body.dark-mode .sidebar-nav li a { color: var(--text-dark-primary); }
body.dark-mode .sidebar-section-title { color: var(--text-dark-secondary); }
body.dark-mode .topbar-nav a { color: var(--text-dark-secondary); }
body.dark-mode .topbar-logo { color: #5cc8db; }
body.dark-mode .post-meta-single { color: var(--text-dark-secondary); border-color: var(--border-dark); }
body.dark-mode .post-tags { border-color: var(--border-dark); }
body.dark-mode .related-section { border-color: var(--border-dark); }
body.dark-mode .related-section h3 { color: var(--text-dark-primary); }
body.dark-mode .post-body blockquote { background: rgba(26,138,158,0.15); }
body.dark-mode .footer-about h3 { color: #5cc8db; }
body.dark-mode .footer-bottom { border-color: var(--border-dark); }
body.dark-mode .theme-toggle { border-color: var(--border-dark); background: var(--bg-dark-card); color: var(--text-dark-secondary); }
body.dark-mode .theme-toggle:hover { background: var(--accent); color: #fff; }
body.dark-mode .mobile-menu-btn { color: var(--text-dark-primary); }
body.dark-mode .sidebar-close-btn { background: var(--bg-dark-card); border-color: var(--border-dark); color: var(--text-dark-primary); }
body.dark-mode .comments-section { border-color: var(--border-dark); }
body.dark-mode .comments-section h3 { color: var(--text-dark-primary); }
body.dark-mode .tag-cloud a { background: rgba(26,138,158,0.2); color: #5cc8db; }
body.dark-mode .archive-list li { border-color: var(--border-dark); }
body.dark-mode .archive-list a { color: var(--text-dark-secondary); }

/* === TOPBAR === */
.topbar {
  position: fixed; top: 0; left: var(--sidebar-w); right: 0;
  height: var(--topbar-h);
  background: var(--bg-card);
  border-bottom: 1px solid var(--border-color);
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 24px;
  z-index: 100;
  backdrop-filter: blur(10px);
}
.topbar-logo { font-family: var(--font-serif); font-size: 1.35rem; font-weight: 700; color: var(--accent); }
.topbar-nav { display: flex; gap: 24px; align-items: center; }
.topbar-nav a { font-size: 0.9rem; font-weight: 500; color: var(--text-secondary); transition: color var(--transition); }
.topbar-nav a:hover { color: var(--accent); }
.topbar-actions { display: flex; gap: 10px; align-items: center; }
.theme-toggle {
  width: 36px; height: 36px; border-radius: 50%;
  border: 1px solid var(--border-color);
  background: var(--bg-card); color: var(--text-secondary);
  cursor: pointer; display: flex; align-items: center; justify-content: center;
  transition: all var(--transition); font-size: 1rem;
}
.theme-toggle:hover { background: var(--accent); color: #fff; border-color: var(--accent); }
.search-box { position: relative; }
.search-box input {
  width: 220px; padding: 8px 36px 8px 14px;
  border: 1px solid var(--border-color);
  border-radius: 20px; font-size: 0.85rem;
  background: var(--bg-primary); color: var(--text-primary);
  outline: none; transition: all var(--transition);
}
.search-box input:focus { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-light); }
.search-box .search-icon {
  position: absolute; right: 12px; top: 50%; transform: translateY(-50%);
  color: var(--text-secondary); font-size: 0.85rem; pointer-events: none;
}

/* === SIDEBAR LEFT === */
.sidebar-left {
  position: fixed; top: 0; left: 0; bottom: 0;
  width: var(--sidebar-w);
  background: var(--bg-card);
  border-right: 1px solid var(--border-color);
  overflow-y: auto; z-index: 110; padding: 20px;
  display: flex; flex-direction: column;
}
.sidebar-left::-webkit-scrollbar { width: 4px; }
.sidebar-left::-webkit-scrollbar-track { background: transparent; }
.sidebar-left::-webkit-scrollbar-thumb { background: var(--border-color); border-radius: 4px; }
.sidebar-brand { padding: 10px 0 20px; text-align: center; border-bottom: 1px solid var(--border-color); margin-bottom: 20px; }
.sidebar-brand h2 { font-family: var(--font-serif); font-size: 1.5rem; color: var(--accent); font-weight: 700; }
.sidebar-brand p { font-size: 0.78rem; color: var(--text-secondary); margin-top: 4px; }
.sidebar-section { margin-bottom: 24px; }
.sidebar-section-title {
  font-size: 0.7rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 1.5px; color: var(--text-secondary);
  margin-bottom: 12px; padding-bottom: 8px;
  border-bottom: 2px solid var(--accent); display: inline-block;
}
.sidebar-nav { list-style: none; }
.sidebar-nav li a {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 12px; border-radius: var(--radius-sm);
  font-size: 0.88rem; font-weight: 500; color: var(--text-primary);
  transition: all var(--transition);
}
.sidebar-nav li a:hover { background: var(--accent-light); color: var(--accent); }
.sidebar-nav li a .nav-icon { font-size: 1rem; width: 20px; text-align: center; }
.popular-item { display: flex; gap: 10px; padding: 10px 0; border-bottom: 1px solid var(--border-color); }
.popular-item:last-child { border-bottom: none; }
.popular-item .pop-thumb { width: 60px; height: 60px; border-radius: var(--radius-sm); object-fit: cover; flex-shrink: 0; }
.popular-item .pop-info { flex: 1; min-width: 0; }
.popular-item .pop-title { font-size: 0.82rem; font-weight: 600; line-height: 1.4; color: var(--text-primary); display: block; }
.popular-item .pop-date { font-size: 0.72rem; color: var(--text-secondary); margin-top: 3px; }

/* === MAIN LAYOUT === */
.main-wrapper { margin-left: var(--sidebar-w); padding-top: var(--topbar-h); min-height: 100vh; display: flex; flex-direction: column; }
.content-area { max-width: 1400px; width: 100%; margin: 0 auto; padding: 24px; display: flex; gap: 24px; flex: 1; }
.main-content { flex: 1; min-width: 0; }

/* === SIDEBAR RIGHT (STICKY) === */
.sidebar-right { width: 300px; flex-shrink: 0; }
.sidebar-right-inner {
  position: sticky; top: calc(var(--topbar-h) + 24px);
  background: var(--bg-card); border-radius: var(--radius); padding: 20px;
  border: 1px solid var(--border-color); box-shadow: var(--shadow-sm);
}
.sidebar-right-inner .sidebar-section-title {
  font-size: 0.7rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 1.5px; color: var(--text-secondary);
  margin-bottom: 14px; padding-bottom: 8px;
  border-bottom: 2px solid var(--accent); display: inline-block;
}
.tag-cloud { display: flex; flex-wrap: wrap; gap: 6px; }
.tag-cloud a {
  display: inline-block; padding: 5px 12px;
  background: var(--accent-light); color: var(--accent);
  border-radius: 20px; font-size: 0.78rem; font-weight: 500;
  transition: all var(--transition);
}
.tag-cloud a:hover { background: var(--accent); color: #fff; }
.archive-list { list-style: none; font-size: 0.84rem; }
.archive-list li { padding: 6px 0; border-bottom: 1px solid var(--border-color); }
.archive-list a { color: var(--text-secondary); }
.archive-list a:hover { color: var(--accent); }

/* === GRID COMMON === */
.grid-section { margin-bottom: 48px; }
.grid-section-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px; }
.grid-section-title {
  font-family: var(--font-serif); font-size: 1.5rem; font-weight: 700;
  color: var(--text-primary); position: relative; padding-left: 14px;
}
.grid-section-title::before {
  content: ''; position: absolute; left: 0; top: 4px; bottom: 4px;
  width: 4px; border-radius: 2px; background: var(--accent);
}
.grid-section .view-all { font-size: 0.85rem; font-weight: 600; color: var(--accent); }
.grid-overlay-card { position: relative; border-radius: var(--radius); overflow: hidden; cursor: pointer; display: block; }
.grid-overlay-card img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; }
.grid-overlay-card:hover img { transform: scale(1.05); }
.grid-overlay-card .grid-overlay {
  position: absolute; bottom: 0; left: 0; right: 0; padding: 20px;
  background: linear-gradient(transparent, rgba(0,0,0,0.75));
}
.grid-overlay-card .grid-cat {
  display: inline-block; padding: 3px 10px;
  background: var(--accent); color: #fff;
  border-radius: 4px; font-size: 0.7rem; font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 6px;
}
.grid-overlay-title { color: #fff; font-size: 1rem; font-weight: 600; line-height: 1.4; }
.grid-overlay-title.lg { font-size: 1.35rem; }

/* 1. BENTO BOX */
.bento-grid { display: grid; grid-template-columns: repeat(4, 1fr); grid-template-rows: 280px 200px; gap: 12px; }
.bento-grid .bento-1 { grid-column: 1 / 3; grid-row: 1 / 3; }
.bento-grid .bento-2 { grid-column: 3; grid-row: 1; }
.bento-grid .bento-3 { grid-column: 4; grid-row: 1; }
.bento-grid .bento-4 { grid-column: 3; grid-row: 2; }
.bento-grid .bento-5 { grid-column: 4; grid-row: 2; }

/* 2. EDITORIAL HERO */
.editorial-grid { display: grid; grid-template-columns: 1.6fr 1fr; grid-template-rows: 200px 200px; gap: 12px; }
.editorial-grid .ed-hero { grid-row: 1 / 3; }
.editorial-grid .ed-2 { grid-column: 2; grid-row: 1; }
.editorial-grid .ed-3 { grid-column: 2; grid-row: 2; }
.editorial-extra { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 12px; }

/* 3. JUSTIFIED FLICKR */
.justified-grid { display: flex; flex-wrap: wrap; gap: 8px; }
.justified-grid .j-item { flex: 1 1 auto; min-width: 150px; height: 220px; }
.justified-grid .j-item:nth-child(1) { flex-basis: 38%; }
.justified-grid .j-item:nth-child(2) { flex-basis: 28%; }
.justified-grid .j-item:nth-child(3) { flex-basis: 30%; }
.justified-grid .j-item:nth-child(4) { flex-basis: 50%; }
.justified-grid .j-item:nth-child(5) { flex-basis: 46%; }

/* 4. SQUARE INSTAGRAM */
.square-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 10px; }
.square-grid .sq-item { aspect-ratio: 1; border-radius: var(--radius-sm); overflow: hidden; position: relative; display: block; }
.square-grid .sq-item img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; }
.square-grid .sq-item:hover img { transform: scale(1.08); }
.square-grid .sq-overlay {
  position: absolute; inset: 0; background: rgba(0,0,0,0);
  display: flex; align-items: flex-end; padding: 12px;
  transition: background var(--transition);
}
.square-grid .sq-item:hover .sq-overlay { background: rgba(0,0,0,0.45); }
.square-grid .sq-overlay span {
  color: #fff; font-size: 0.82rem; font-weight: 600;
  opacity: 0; transform: translateY(8px); transition: all var(--transition);
}
.square-grid .sq-item:hover .sq-overlay span { opacity: 1; transform: translateY(0); }

/* 5. ASYMMETRIC */
.asym-grid { display: grid; grid-template-columns: repeat(3, 1fr); grid-template-rows: 250px 220px; gap: 12px; }
.asym-grid .asym-1 { grid-column: 1 / 3; grid-row: 1; }
.asym-grid .asym-2 { grid-column: 3; grid-row: 1; margin-top: 30px; }
.asym-grid .asym-3 { grid-column: 1; grid-row: 2; margin-top: -30px; }
.asym-grid .asym-4 { grid-column: 2 / 4; grid-row: 2; }

/* === ARTICLE CARDS === */
.article-cards-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; margin-top: 48px; }
.article-card {
  background: var(--bg-card); border-radius: var(--radius); overflow: hidden;
  border: 1px solid var(--border-color); box-shadow: var(--shadow-sm);
  transition: all var(--transition);
}
.article-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-3px); }
.article-card .card-thumb { width: 100%; height: 190px; object-fit: cover; }
.article-card .card-body { padding: 16px; }
.category-tag {
  display: inline-block; padding: 3px 10px;
  background: var(--accent-light); color: var(--accent);
  border-radius: 4px; font-size: 0.7rem; font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 8px;
}
.article-card .card-title {
  font-family: var(--font-serif); font-size: 1.05rem; font-weight: 600;
  line-height: 1.45; color: var(--text-primary);
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}
.article-card .card-excerpt {
  font-size: 0.84rem; color: var(--text-secondary); margin-top: 8px; line-height: 1.5;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}
.article-card .card-meta {
  display: flex; align-items: center; justify-content: space-between;
  margin-top: 12px; padding-top: 12px; border-top: 1px solid var(--border-color);
  font-size: 0.75rem; color: var(--text-secondary);
}

/* === SINGLE POST === */
.post-wrapper { max-width: 780px; margin: 0 auto; }
.breadcrumb { font-size: 0.82rem; color: var(--text-secondary); margin-bottom: 20px; }
.breadcrumb a { color: var(--accent); }
.post-title-single {
  font-family: var(--font-serif); font-size: 2.2rem; font-weight: 700;
  line-height: 1.3; color: var(--text-primary); margin-bottom: 16px;
}
.post-meta-single {
  display: flex; gap: 16px; align-items: center;
  font-size: 0.84rem; color: var(--text-secondary);
  margin-bottom: 24px; padding-bottom: 16px; border-bottom: 1px solid var(--border-color);
}
.post-featured-img { width: 100%; height: auto; border-radius: var(--radius); margin-bottom: 28px; }
.post-body { font-size: 1.05rem; line-height: 1.8; color: var(--text-primary); }
.post-body h2, .post-body h3 { font-family: var(--font-serif); margin: 28px 0 12px; font-weight: 700; }
.post-body h2 { font-size: 1.5rem; }
.post-body h3 { font-size: 1.25rem; }
.post-body p { margin-bottom: 16px; }
.post-body img { border-radius: var(--radius); margin: 20px 0; }
.post-body blockquote {
  border-left: 4px solid var(--accent); padding: 16px 20px; margin: 20px 0;
  background: var(--accent-light); border-radius: 0 var(--radius-sm) var(--radius-sm) 0; font-style: italic;
}
.post-tags {
  display: flex; flex-wrap: wrap; gap: 6px; margin-top: 30px; padding-top: 20px;
  border-top: 1px solid var(--border-color);
}
.post-tags a {
  display: inline-block; padding: 5px 14px;
  background: var(--accent-light); color: var(--accent);
  border-radius: 20px; font-size: 0.78rem; font-weight: 500;
  transition: all var(--transition);
}
.post-tags a:hover { background: var(--accent); color: #fff; }

/* === RELATED POSTS === */
.related-section { margin-top: 48px; padding-top: 32px; border-top: 1px solid var(--border-color); }
.related-section h3 {
  font-family: var(--font-serif); font-size: 1.3rem; font-weight: 700;
  margin-bottom: 20px; color: var(--text-primary);
}
.related-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.related-card {
  background: var(--bg-card); border-radius: var(--radius); overflow: hidden;
  border: 1px solid var(--border-color); transition: all var(--transition); display: block;
}
.related-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.related-card img { width: 100%; height: 150px; object-fit: cover; }
.related-card h4 {
  padding: 12px 14px; font-size: 0.9rem; font-weight: 600; line-height: 1.4;
  color: var(--text-primary);
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}

/* === SCROLL TO TOP === */
.scroll-top-btn {
  position: fixed; bottom: 28px; right: 28px;
  width: 46px; height: 46px; border-radius: 50%;
  background: var(--accent); color: #fff; border: none; cursor: pointer;
  display: none; align-items: center; justify-content: center;
  font-size: 1.2rem;
  box-shadow: 0 4px 16px rgba(26,138,158,0.4);
  transition: all var(--transition); z-index: 999;
}
.scroll-top-btn.visible { display: flex; }
.scroll-top-btn:hover { transform: translateY(-3px); box-shadow: 0 6px 24px rgba(26,138,158,0.5); }

/* === FOOTER === */
.footer-wrapper {
  background: var(--bg-card); border-top: 1px solid var(--border-color);
  margin-top: 60px; padding: 40px 24px 20px;
}
.footer-inner { max-width: 1100px; margin: 0 auto; display: grid; grid-template-columns: 2fr 1fr 1fr; gap: 40px; }
.footer-about h3 { font-family: var(--font-serif); font-size: 1.2rem; color: var(--accent); margin-bottom: 10px; }
.footer-about p { font-size: 0.85rem; color: var(--text-secondary); line-height: 1.6; }
.footer-links h4 { font-size: 0.85rem; font-weight: 700; margin-bottom: 12px; text-transform: uppercase; letter-spacing: 1px; }
.footer-links ul { list-style: none; }
.footer-links li { margin-bottom: 6px; }
.footer-links a { font-size: 0.84rem; color: var(--text-secondary); }
.footer-links a:hover { color: var(--accent); }
.footer-bottom {
  text-align: center; margin-top: 30px; padding-top: 20px;
  border-top: 1px solid var(--border-color); font-size: 0.8rem; color: var(--text-secondary);
}
.comments-section { margin-top: 40px; padding-top: 24px; border-top: 1px solid var(--border-color); }

/* Mobile */
.mobile-menu-btn {
  display: none; width: 36px; height: 36px; border: none;
  background: transparent; font-size: 1.3rem;
  color: var(--text-primary); cursor: pointer;
  align-items: center; justify-content: center;
}
.sidebar-close-btn {
  display: none; position: absolute; top: 14px; right: 14px;
  width: 30px; height: 30px; border-radius: 50%;
  border: 1px solid var(--border-color); background: var(--bg-card);
  cursor: pointer; font-size: 1rem; color: var(--text-primary);
  align-items: center; justify-content: center;
}
.mobile-overlay {
  display: none; position: fixed; inset: 0;
  background: rgba(0,0,0,0.5); z-index: 105;
}

@media (max-width: 1024px) {
  .sidebar-right { display: none; }
  .article-cards-grid { grid-template-columns: repeat(2, 1fr); }
  .related-grid { grid-template-columns: repeat(2, 1fr); }
  .square-grid { grid-template-columns: repeat(3, 1fr); }
  .bento-grid { grid-template-columns: repeat(2, 1fr); grid-template-rows: auto; }
  .bento-grid .bento-1 { grid-column: 1 / 3; }
  .bento-grid .bento-2, .bento-grid .bento-3, .bento-grid .bento-4, .bento-grid .bento-5 { grid-column: auto; }
  .editorial-grid { grid-template-columns: 1fr; grid-template-rows: auto; }
  .editorial-grid .ed-hero { grid-column: 1; grid-row: auto; }
  .asym-grid { grid-template-columns: 1fr 1fr; grid-template-rows: auto; }
  .asym-grid .asym-1 { grid-column: 1 / 3; }
  .asym-grid .asym-2 { margin-top: 0; }
  .asym-grid .asym-3 { margin-top: 0; }
  .asym-grid .asym-4 { grid-column: auto; }
  .footer-inner { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  :root { --sidebar-w: 0px; }
  .sidebar-left { transform: translateX(-100%); width: 270px; transition: transform var(--transition); }
  .sidebar-left.open { transform: translateX(0); }
  .sidebar-close-btn { display: flex; }
  .mobile-menu-btn { display: flex; }
  .mobile-overlay.active { display: block; }
  .topbar { left: 0; }
  .topbar-nav { display: none; }
  .main-wrapper { margin-left: 0; }
  .content-area { padding: 16px; }
  .article-cards-grid { grid-template-columns: 1fr; }
  .related-grid { grid-template-columns: 1fr; }
  .square-grid { grid-template-columns: repeat(2, 1fr); }
  .justified-grid .j-item { min-width: 100%; height: 180px; }
  .bento-grid { grid-template-columns: 1fr; grid-template-rows: auto; }
  .bento-grid .bento-1 { grid-column: 1; }
  .post-title-single { font-size: 1.6rem; }
  .search-box input { width: 140px; }
  .scroll-top-btn { bottom: 18px; right: 18px; width: 40px; height: 40px; font-size: 1rem; }
}

body.script:
//

// Footer year
(function(){
  var el=document.getElementById('footerYear');
  if(el){
    var t=document.querySelector('.topbar-logo');
    var n=t?t.textContent:'Pena Edukasi';
    el.innerHTML='\u00A9 '+new Date().getFullYear()+' '+n+'. All Rights Reserved.';
  }
})();

// === DARK MODE ===
(function(){
  var btn=document.getElementById('themeToggle');
  function setDark(isDark){
    if(isDark){
      document.body.classList.add('dark-mode');
      if(btn)btn.innerHTML='\u2600';
      try{localStorage.setItem('pe-theme','dark');}catch(e){}
    }else{
      document.body.classList.remove('dark-mode');
      if(btn)btn.innerHTML='\uD83C\uDF19';
      try{localStorage.setItem('pe-theme','light');}catch(e){}
    }
  }
  try{
    var saved=localStorage.getItem('pe-theme');
    if(saved==='dark')setDark(true);
  }catch(e){}
  if(btn)btn.addEventListener('click',function(){
    setDark(!document.body.classList.contains('dark-mode'));
  });
})();

// === SCROLL TO TOP ===
(function(){
  var btn=document.getElementById('scrollTopBtn');
  if(!btn)return;
  window.addEventListener('scroll',function(){
    if(window.scrollY>400){btn.classList.add('visible');}
    else{btn.classList.remove('visible');}
  });
  btn.addEventListener('click',function(){
    window.scrollTo({top:0,behavior:'smooth'});
  });
})();

// === MOBILE SIDEBAR ===
(function(){
  var sidebar=document.getElementById('sidebarLeft');
  var overlay=document.getElementById('mobileOverlay');
  var openBtn=document.getElementById('mobileMenuBtn');
  var closeBtn=document.getElementById('sidebarCloseBtn');
  function openSidebar(){
    if(sidebar)sidebar.classList.add('open');
    if(overlay)overlay.classList.add('active');
  }
  function closeSidebar(){
    if(sidebar)sidebar.classList.remove('open');
    if(overlay)overlay.classList.remove('active');
  }
  if(openBtn)openBtn.addEventListener('click',openSidebar);
  if(closeBtn)closeBtn.addEventListener('click',closeSidebar);
  if(overlay)overlay.addEventListener('click',closeSidebar);
})();

// === FEED HELPER ===
function peGetThumb(e){
  if(e.media$thumbnail)return e.media$thumbnail.url.replace(/\/s72-c/,'/s600');
  var c=e.content?e.content.$t:(e.summary?e.summary.$t:'');
  var m=c.match(/<img[^>]+src=["']([^"']+)/);
  return m?m[1]:'https://via.placeholder.com/600x400/1a8a9e/ffffff?text=Pena+Edukasi';
}
function peGetLink(e){
  for(var i=0;i<e.link.length;i++){if(e.link[i].rel==='alternate')return e.link[i].href;}
  return '#';
}
function peGetTitle(e){return e.title.$t;}
function peGetCat(e){return e.category?e.category[0].term:'';}

function peOverlayCard(e,cls,lg){
  var tc=lg?'grid-overlay-title lg':'grid-overlay-title';
  var t=peGetTitle(e).replace(/"/g,'&amp;quot;');
  return '<a href="'+peGetLink(e)+'" class="grid-overlay-card '+cls+'">'+
    '<img src="'+peGetThumb(e)+'" alt="'+t+'"/>'+
    '<div class="grid-overlay"><span class="grid-cat">'+peGetCat(e)+'</span>'+
    '<div class="'+tc+'">'+peGetTitle(e)+'</div></div></a>';
}

function peFetchLabel(label,count,cb){
  var s=document.createElement('script');
  var cn='__peCb_'+label.replace(/[^a-zA-Z0-9]/g,'')+'_'+Math.random().toString(36).substr(2,5);
  window[cn]=function(d){
    cb(d.feed?d.feed.entry||[]:[]);
    try{delete window[cn];}catch(x){window[cn]=undefined;}
  };
  s.src='/feeds/posts/summary/-/'+encodeURIComponent(label)+'?alt=json-in-script&max-results='+count+'&callback='+cn;
  document.body.appendChild(s);
}

// Grid 1: Bento (Pendidikan)
peFetchLabel('Pendidikan',5,function(en){
  var g=document.getElementById('bentoGrid');
  if(!g||en.length<1)return;
  var h='';
  for(var i=0;i<Math.min(en.length,5);i++){h+=peOverlayCard(en[i],'bento-'+(i+1),i===0);}
  g.innerHTML=h;
});

// Grid 2: Editorial (Kurikulum)
peFetchLabel('Kurikulum',5,function(en){
  var g=document.getElementById('editorialGrid');
  if(!g||en.length<1)return;
  var h=peOverlayCard(en[0],'ed-hero',true);
  if(en[1])h+=peOverlayCard(en[1],'ed-2',false);
  if(en[2])h+=peOverlayCard(en[2],'ed-3',false);
  g.innerHTML=h;
  if(en.length>3){
    var ex=document.createElement('div');
    ex.className='editorial-extra';
    var eh='';
    for(var i=3;i<Math.min(en.length,5);i++){eh+=peOverlayCard(en[i],'',false);}
    ex.innerHTML=eh;
    g.parentNode.appendChild(ex);
  }
});

// Grid 3: Justified (Materi)
peFetchLabel('Materi',5,function(en){
  var g=document.getElementById('justifiedGrid');
  if(!g||en.length<1)return;
  var h='';
  for(var i=0;i<Math.min(en.length,5);i++){h+=peOverlayCard(en[i],'j-item',false);}
  g.innerHTML=h;
});

// Grid 4: Square (Tutorial)
peFetchLabel('Tutorial',5,function(en){
  var g=document.getElementById('squareGrid');
  if(!g||en.length<1)return;
  var h='';
  for(var i=0;i<Math.min(en.length,5);i++){
    var t=peGetTitle(en[i]).replace(/"/g,'&amp;quot;');
    h+='<a href="'+peGetLink(en[i])+'" class="sq-item">'+
      '<img src="'+peGetThumb(en[i])+'" alt="'+t+'"/>'+
      '<div class="sq-overlay"><span>'+peGetTitle(en[i])+'</span></div></a>';
  }
  g.innerHTML=h;
});

// Grid 5: Asymmetric (Madrasah)
peFetchLabel('Madrasah',5,function(en){
  var g=document.getElementById('asymGrid');
  if(!g||en.length<1)return;
  var h='';
  var cls=['asym-1','asym-2','asym-3','asym-4','asym-5'];
  for(var i=0;i<Math.min(en.length,5);i++){h+=peOverlayCard(en[i],cls[i]||'',i===0);}
  g.innerHTML=h;
});

// === RELATED POSTS (3 Artikel Terkait) ===
(function(){
  var c=document.getElementById('relatedPosts');
  if(!c)return;
  var tags=document.querySelectorAll('.post-tags a');
  var label='';
  if(tags.length>0){label=tags[0].textContent.replace('#','').trim();}
  if(!label)return;
  var cur=window.location.href;
  var s=document.createElement('script');
  var cn='__peRelated'+Math.random().toString(36).substr(2,5);
  window[cn]=function(d){
    var en=d.feed?d.feed.entry||[]:[]; var h=''; var ct=0;
    for(var i=0;i<en.length&&ct<3;i++){
      var lk=peGetLink(en[i]);
      if(lk===cur)continue;
      var t=peGetTitle(en[i]).replace(/"/g,'&amp;quot;');
      h+='<a href="'+lk+'" class="related-card">'+
        '<img src="'+peGetThumb(en[i])+'" alt="'+t+'"/>'+
        '<h4>'+peGetTitle(en[i])+'</h4></a>';
      ct++;
    }
    c.innerHTML=h;
    try{delete window[cn];}catch(x){window[cn]=undefined;}
  };
  s.src='/feeds/posts/summary/-/'+encodeURIComponent(label)+'?alt=json-in-script&max-results=4&callback='+cn;
  document.body.appendChild(s);
})();

//
